INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"Hero Intro","content":"We remodel kitchens, bathrooms, basements, and more for homeowners across Fairfield County and New Haven County, Connecticut. We communicate clearly, we show up when we say we will, and we finish the job. That''s what sets us apart, and it''s the reason most of our clients never need to look for a contractor again.\n\nCT Home Improvement Contractor License #0668405\nFairfield County: (203) 919-9616 | New Haven County: (203) 466-9148","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"default","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 2, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'services_grid', '{"title":"Primary Services","subtitle":"We handle the full range of interior home remodeling, from individual rooms to whole-home renovations. Whether you''re replacing a dated kitchen, finishing an unused basement, or adding square footage with a home addition, we bring the same standard of work and communication to every project.","items":[{"title":"Kitchen Remodeling","summary":"The kitchen is the most-used room in your home, and a full remodel touches everything: cabinets, countertops, layout, plumbing, lighting, and flooring.","image":null,"url":"/kitchen-remodeling/","cta_label":"Learn More"},{"title":"Bathroom Remodeling","summary":null,"image":null,"url":"/bathroom-remodeling/","cta_label":"Learn More"},{"title":"Basement Finishing","summary":"An unfinished basement is usable square footage you''re not using.","image":null,"url":"/basement-finishing/","cta_label":"Learn More"},{"title":"Home Additions","summary":"When you''ve outgrown your current floor plan, an addition gives you the space you need without giving up the neighborhood you chose.","image":null,"url":"/home-additions/","cta_label":"Learn More"}]}', 3, 1, NOW(), NOW());
