INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"What We Do","content":"We handle the full range of interior home remodeling, from individual rooms to whole-home renovations. Whether you''re replacing a dated kitchen, finishing an unused basement, or adding square footage with a home addition, we bring the same standard of work and communication to every project.\n\n--- PRIMARY SERVICES ---\n\nH3: Kitchen Remodeling\nThe kitchen is the most-used room in your home, and a full remodel touches everything: cabinets, countertops, layout, plumbing, lighting, and flooring. We plan every kitchen project in detail before a single wall opens, so you know exactly what''s happening and when. Learn more about our kitchen remodeling services.\n\nH3: Bathroom Remodeling\nFrom a single bathroom refresh to a complete primary suite overhaul, we handle tile, fixtures, vanities, shower systems, and all the finish work that makes the difference between a bathroom that looks fine and one that holds up for decades. Learn more about our bathroom remodeling services.\n\nH3: Basement Finishing\nAn unfinished basement is usable square footage you''re not using. We turn it into living space: a family room, home office, guest suite, gym, or anything in between, properly framed, insulated, drywalled, lit, and finished to match the rest of your home. Learn more about our basement finishing services.\n\nH3: Home Additions\nWhen you''ve outgrown your current floor plan, an addition gives you the space you need without giving up the neighborhood you chose. We manage the full scope: design coordination, permits, foundation, framing, and all interior and exterior finish work. Learn more about our home addition services.\n\n--- SECONDARY SERVICES ---\n\nH3: Flooring Installation\nWe install hardwood, engineered wood, luxury vinyl plank, and tile throughout your home. New flooring is one of the highest-impact changes you can make, and we install it right the first time so it lasts. Learn more about our flooring installation services.\n\nH3: Interior Painting\nA clean, well-applied coat of paint changes how every room feels. We prep surfaces properly, protect your furniture and trim, and deliver clean lines and consistent coverage throughout. Learn more about our interior painting services.\n\nH3: Interior Carpentry\nCrown molding, built-in shelving, wainscoting, coffered ceilings, and custom trim work are where craftsmanship shows. We take on the detail work that makes a finished space look intentional. Learn more about our interior carpentry services.\n\nH3: Attic Conversions\nIf your attic has enough headroom, it can become a bedroom, office, or bonus room. We assess the structural requirements, handle insulation and HVAC extensions, and convert unused overhead space into a finished room with full permits. Learn more about our attic conversion services.\n\nH3: Decks and Porches\nOutdoor living space adds real value, and it requires real craftsmanship to hold up through Connecticut winters. We build decks and porches to last, using materials appropriate for the exposure and construction methods that meet local code. Learn more about our deck and porch services.\n\nH3: Design and Planning\nNot every homeowner comes in with a finished design. We offer structured planning and design guidance to help you clarify scope, finalize selections, and move into construction with a plan that reflects what you actually want. Learn more about our design and planning services.\n\nH3: Comfort and Accessibility Remodeling\nWe install grab bars, wider doorways, walk-in showers, step-free transitions, and other modifications that make your home more comfortable and more functional at any stage of life. These projects are built to the same standard as any other remodel we do. Learn more about our comfort and accessibility remodeling services.\n\nView all our services.","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"cards","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 5, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"Why Homeowners Choose BuiltWell CT","content":"Remodeling has a reputation problem. Contractors who disappear, timelines that stretch from weeks into months, phone calls that go unanswered: most homeowners have a story. We built BuiltWell CT around three commitments that address those problems directly.\n\nH3: We Communicate\nYou''ll know what''s happening on your project every day. Before we start, you receive a written proposal that spells out exactly what''s included, what the timeline looks like, and what the cost is. Once construction begins, you get daily updates so you''re never left wondering. If something changes, we tell you immediately; we don''t wait until you notice.\n\nH3: We Show Up\nWe keep the schedule we commit to. Our crews arrive on time, work a full day, and clean the job site before they leave each evening. You shouldn''t have to live in a construction zone that looks abandoned at the end of every day. We don''t leave tools scattered, materials piled in your hallway, or dust on surfaces that were supposed to be protected. A clean site is part of the job.\n\nH3: We Finish What We Start\nProjects end. Punch lists get completed. Walk-throughs happen on schedule. We don''t consider a job done until you''ve walked through it with us and told us it''s right. If something isn''t what you expected, we fix it before we close out. That standard is why so many of our clients refer us to family and friends, and why they call us again when the next project comes up.","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"default","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 6, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'process_steps', '{"title":"How It Works","subtitle":"We follow the same five-step process on every project, whether it''s a single bathroom or a whole-home renovation. It keeps projects on schedule and keeps you informed at every stage. Learn more about how we work.","steps":[{"title":"Step 1: Consultation","short":"Step 1: Consultation","description":"We visit your home or connect via Google Meet or Zoom at no charge and with no obligation, so we can understand the scope before we put anything in writing."},{"title":"Step 2: Planning","short":"Step 2: Planning","description":"You receive a written proposal with a clear breakdown of exactly what''s included, the full project timeline, and the cost. No vague ranges, no surprises later."},{"title":"Step 3: Selections","short":"Step 3: Selections","description":"We guide you through every material choice and communicate lead times upfront, so nothing delays construction once the schedule is set."},{"title":"Step 4: Build","short":"Construction begins on the agreed start date.","description":"Construction begins on the agreed start date. Crews show up on time, daily updates are sent, and the job site is cleaned every evening before anyone leaves."},{"title":"Step 5: Walkthrough","short":"When the work is finished, we walk through the project together.","description":"When the work is finished, we walk through the project together. Nothing is signed off until you''re satisfied with every detail."}]}', 7, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"Where We Work","content":"We serve homeowners throughout Fairfield County and New Haven County, Connecticut. If your town isn''t listed below, contact us, as we may still be able to help. See all areas we serve.\n\nH3: Fairfield County\nWe serve Greenwich, Stamford, Norwalk, Westport, Darien, New Canaan, Fairfield, and Wilton, along with the surrounding communities throughout the county. Learn more about our work in Fairfield County.\n\nH3: New Haven County\nWe serve New Haven, Milford, West Haven, Hamden, Orange, Derby, Shelton, and Woodbridge, along with the surrounding communities throughout the county. Learn more about our work in New Haven County.","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"links","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 8, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'areas_served', '{"title":"Areas We Serve","subtitle":"We serve homeowners throughout Fairfield County and New Haven County, Connecticut. If your town isn''t listed below, contact us, as we may still be able to help. See all areas we serve.","counties":[{"name":"Fairfield County","towns":["Greenwich","Stamford","Norwalk","Westport","Darien","New Canaan","Fairfield","Wilton"],"image":null,"url":"/fairfield-county/"},{"name":"New Haven County","towns":["New Haven","Milford","West Haven","Hamden","Orange","Derby","Shelton","Woodbridge"],"image":null,"url":"/new-haven-county/"}],"show_map":true}', 9, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"Recent Projects","content":"Here''s a look at three projects we''ve completed recently. You can read the full write-ups in our case studies.\n\nH3: Kitchen Remodel in New Canaan, CT\nThe clients wanted their kitchen opened up. That meant removing a load-bearing wall, which we engineered and executed properly before anything else moved forward. We installed white shaker cabinets, a four-seat island, quartz countertops, and hardwood flooring throughout. The project ran ten weeks from demo to final walkthrough.\n\n\"BuiltWell made it straightforward.\" - The Chens\n\nRead the full New Canaan kitchen case study.\n\nH3: Basement Finishing in Darien, CT\nAn 850-square-foot unfinished basement with a new egress window became a fully finished lower level in six weeks. Framed, insulated, drywalled, lit, and floored. The family had lived with that space untouched for years and immediately wished they''d done it sooner.\n\n\"We should have done this ten years ago.\" - Steve R.\n\nRead the full Darien basement case study.\n\nH3: Bathroom Remodel in Westport, CT\nA full bathroom gut and rebuild, including a new walk-in shower, completed in four weeks. The client had put this project off for years, and once it was done, the wait felt longer than the construction.\n\n\"Four weeks of construction, and now I have the bathroom I''ve been dreaming about.\" - Jennifer M.\n\nRead the full Westport bathroom case study.\n\nSee all case studies.","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"links","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 10, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'project_highlights', '{"eyebrow":"Recent Projects","title":"Recent Projects","items":[{"title":"Kitchen Remodel in New Canaan, CT","description":"The clients wanted their kitchen opened up.","image":"builtwell-ct-before-after-kitchen-new-canaan.webp","url":"/case-studies/kitchen-remodeling-new-canaan/","tag":"The Chens"},{"title":"Basement Finishing in Darien, CT","description":"An 850-square-foot unfinished basement with a new egress window became a fully finished lower level in six weeks.","image":"builtwell-ct-finished-basement-darien.webp","url":"/case-studies/basement-finishing-darien/","tag":"Steve R."},{"title":"Bathroom Remodel in Westport, CT","description":"A full bathroom gut and rebuild, including a new walk-in shower, completed in four weeks.","image":"builtwell-ct-bathroom-remodel-westport.webp","url":"/case-studies/bathroom-remodeling-westport/","tag":"Jennifer M."}]}', 11, 1, NOW(), NOW());
INSERT INTO sections (page_id, type, data, sort_order, is_active, created_at, updated_at) VALUES (2, 'rich_text', '{"eyebrow":null,"title":"Licensed and Insured in Connecticut","content":"We hold CT Home Improvement Contractor License #0668405, issued by the State of Connecticut Department of Consumer Protection. We carry general liability insurance and workers'' compensation coverage on every project.\n\nWhat that means for you: if something goes wrong on your property during construction, you''re protected. You''re not left dealing with an uninsured contractor and a coverage dispute. We work with licensed, insured subcontractors when specialty trades are involved, and we carry the documentation to prove it. Hiring a licensed contractor isn''t just a formality; it''s how you protect your home and your investment.","image":null,"image_alt":null,"image_position":"right","cta":{"label":"","url":""},"align":"left","variant":"default","style_variant":"default","surface":"default","container_width":"default","spacing":"normal","anchor_id":null}', 12, 1, NOW(), NOW());
